/// <summary>
/// Extension class of form data source SalesTable in form SalesTable
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesTable))]
public final class METSalesTableFormSalesTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// active method on ST datasource
    /// </summary>
    /// <returns>
    /// int
    /// </returns>
    int active()
    {
        int ret = next active();

        this.METEnableCustomBtn();

        return ret;
    }

    /// <summary>
    /// enable/disable custom buttons
    /// </summary>
    private void METEnableCustomBtn()
    {
        SalesTable salesTable = this.cursor() as SalesTable;
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderCancellation))).enabled(salesTable.SalesStatus == SalesStatus::Canceled);
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderCreation))).enabled(salesTable.METAllowTMSCreation());
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderPickingList))).enabled(salesTable.METAllowTMSExtraction());

        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METAllowBackOrders))).enabled(false);

        if (salesTable.DataAreaId != InventParameters::find().METInterCompanyPurchaseLegalEntity)
        {
            this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, SalesTable_METIntercompanyTransferFulfillment))).enabled(false);
        }
    }

/// <summary>
/// Performs write action on the datasource to peform insert of active record.
/// </summary>
public void write()
{
    next write();
    FormDataSource fds = this;
    FormDataSource fdsMETSalesTable_ExtFields = fds.formRun().dataSource(formDataSourceStr(SalesTable, METSalesTable));
    SalesTable salesTable = fds.cursor();

    if (fdsMETSalesTable_ExtFields && METSalesTable::findBySalesTable(salesTable.RecId).RecId == 0 )
    {
        METSalesTable metSalesTableLocal = fdsMETSalesTable_ExtFields.cursor();
        salesTable.metPackMETSalesTable(metSalesTableLocal);
        metSalesTableLocal.SysExtensionSerializerExtensionMap::insertAfterBaseTable(salesTable);
    }
}
